contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public entry with all logic
    function run(address proposedAddress, string memory typ) public payable {
        // require a non-zero proposed address to avoid obvious reverts in moveUtils/moveRewardAddress later
        require(proposedAddress != address(0));

        // Create a new address proposal: this increments proposalCount and stores the proposedAddress
        c.newAddressProposal(proposedAddress, typ); if (__ESBMC_reverted()) return;

        // read the latest proposal id
        uint pid = c.proposalCount(); if (__ESBMC_reverted()) return;

        // read the stored address immediately after creation
        address storedBefore = c.mapPID_address(pid); if (__ESBMC_reverted()) return;

        // attempt to vote on the proposal; capture whether it reverted
        bool reverted;
        uint voteOut;
        reverted = false;
        uint256 v = c.voteProposal(pid); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            voteOut = v;
        }

        // read the stored address after voting/finalisation attempt
        address storedAfter = c.mapPID_address(pid); if (__ESBMC_reverted()) return;

        // General invariant: newAddressProposal sets mapPID_address[pid] and subsequent voteProposal should not change that address
        assert(storedBefore == proposedAddress && storedAfter == storedBefore);
    }

    receive() external payable { }
}

