pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DAO c;

    function setUp() public {
        c = new DAO();
    }

    function _run(address proposedAddress, string memory typ) internal {
        vm.assume(proposedAddress != address(0));
        try c.newAddressProposal(proposedAddress, typ) {} catch { return; }
        uint256 pid;
        try c.proposalCount() returns (uint256 __r) { pid = __r; } catch { return; }
        address storedBefore;
        try c.mapPID_address(pid) returns (address __r) { storedBefore = __r; } catch { return; }
        bool reverted;
        uint voteOut;
        reverted = false;
        try c.voteProposal(pid) returns (uint v) {
            voteOut = v;
        } catch {
            reverted = true;
        }
        address storedAfter;
        try c.mapPID_address(pid) returns (address __r) { storedAfter = __r; } catch { return; }
        assertTrue(storedBefore == proposedAddress && storedAfter == storedBefore);
    }

    function testFuzz_run(address proposedAddress, string memory typ) public {
